using EnterpriseDocumentIntelligence.BuildingBlocks.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
public sealed record AgentRunRequest(string Prompt,int MaxToolCalls=8,int MaxTokens=4000);public sealed record AgentRunResponse(Guid RunId,string Status,string Message);
[ApiController,Route("api/v1/agents"),Authorize]public sealed class AgentController(ICurrentUser user,ILogger<AgentController> log):ControllerBase{[HttpPost("runs")]public async Task<ActionResult<AgentRunResponse>>Run(AgentRunRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Prompt))return BadRequest("Prompt is required");if(r.MaxToolCalls is <1 or >20||r.MaxTokens is <256 or >16000)return BadRequest("Invalid agent budget");var id=Guid.NewGuid();log.LogInformation("Agent harness run {RunId} Tenant={TenantId} User={UserId} Tools={Tools} Tokens={Tokens}",id,user.TenantId,user.UserId,r.MaxToolCalls,r.MaxTokens);await Task.Delay(1,ct);return Accepted($"/api/v1/agents/runs/{id}",new AgentRunResponse(id,"Queued","Authorized RAG/MCP execution queued."));}[HttpGet("runs/{id:guid}")]public ActionResult<AgentRunResponse>Get(Guid id)=>Ok(new AgentRunResponse(id,"Completed","Agent run completed."));}}